mapper.select:
SELECT ChnlCode, StoreCode, StoreImgCode, StoreImgName, StoreImgDesc, StoreImgLink, StoreImgWidth, StoreImgHeight, StoreImgHtml, NewwinYn, Remark, State, RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName FROM shopion.tStrStoreImg
AND ChnlCode = #{pChnlCode}
AND StoreCode = #{pStoreCode}
ORDER BY StoreImgCode

SELECT ChnlCode, StoreCode, StoreImgCode, StoreImgName, StoreImgDesc,
       StoreImgLink, StoreImgWidth, StoreImgHeight, StoreImgHtml, NewwinYn,
       Remark, State, RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName
FROM shopion.tStrStoreImg
WHERE ChnlCode = #{pChnlCode}
  AND StoreCode = #{pStoreCode}
  AND StoreImgCode = #{pStoreImgCode}

SELECT StoreImgHtml
FROM shopion.tStrStoreImg
WHERE ChnlCode = #{pChnlCode}
  AND StoreCode = #{pStoreCode}
  AND StoreImgCode = #{pStoreImgCode}

